 "content": "from collections import deque


def transform(grid):
    """Fill each hollow rectangular outline: odd interior area -> 7, even -> 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            if y1 - y0 < 2 or x1 - x0 < 2:
                continue
            perimeter = ({(y0, x) for x in range(x0, x1 + 1)} |
                         {(y1, x) for x in range(x0, x1 + 1)} |
                         {(y, x0) for y in range(y0, y1 + 1)} |
                         {(y, x1) for y in range(y0, y1 + 1)})
            if cells != perimeter:
                continue
            if any(grid[y][x] != background
                   for y in range(y0 + 1, y1)
                   for x in range(x0 + 1, x1)):
                continue

            fill = 7 if ((y1 - y0 - 1) * (x1 - x0 - 1)) % 2 else 2
            for y in range(y0 + 1, y1):
                for x in range(x0 + 1, x1):
                    out[y][x] = fill
    return out


if __name__ == '__main__':
    pass
